typedef unsigned long long ull;
ull full;
int h;
ull classmask[64][7];
ull closureOf(ull S){
  if(!S)return 0;
  ull G=full;
  for(int x=0;x<p;x++){
    int v=-1;bool ok=true;
    for(int i=0;i<p;i++)if(S>>i&1){ if(v==-1)v=f[i][x]; else if(f[i][x]!=v){ok=false;break;} }
    if(ok)G &= classmask[x][v];
  }
  return G;
}
int agreeMaskCount(ull S){ // count positions where constant
  int c=0;
  for(int x=0;x<p;x++){
    int v=-1;bool ok=true;
    for(int i=0;i<p;i++)if(S>>i&1){ if(v==-1)v=f[i][x]; else if(f[i][x]!=v){ok=false;break;} }
    if(ok)c++;
  }
  return c;
}
vector<ull> exactClosedMax(){
  vector<ull> classes;
  for(int x=0;x<p;x++)for(int r=0;r<7;r++)if(classmask[x][r])classes.push_back(classmask[x][r]);
  set<ull> closedSet; queue<ull> q;
  for(ull c:classes){ull G=closureOf(c); if(G && !closedSet.count(G)){closedSet.insert(G);q.push(G);} }
  while(!q.empty()){
    ull C=q.front();q.pop();
    for(ull c:classes){ull G=closureOf(C & c); if(G && !closedSet.count(G)){closedSet.insert(G);q.push(G);} }
  }
  vector<ull> cand;
  for(ull C:closedSet) if(agreeMaskCount(C)>=h) cand.push_back(C);
  vector<ull> res;
  for(ull A:cand){bool mx=true;for(ull B:cand)if(A!=B && (A|B)==B){mx=false;break;}if(mx)res.push_back(A);}
  return res;
}
vector<ull> pairCand(){
  vector<ull> cand;
  for(int i=0;i<p;i++){ull S=1ULL<<i;ull G=closureOf(S); if(G && agreeMaskCount(G)>=h)cand.push_back(G);}
  for(int i=0;i<p;i++)for(int j=i+1;j<p;j++){ull S=(1ULL<<i)|(1ULL<<j);ull G=closureOf(S); if(G && agreeMaskCount(G)>=h)cand.push_back(G);}
  vector<ull> res;
  for(ull A:cand){bool mx=true;for(ull B:cand)if(A!=B && (A|B)==B){mx=false;break;}if(mx)res.push_back(A);}
  sort(res.begin(),res.end());res.erase(unique(res.begin(),res.end()),res.end());
  return res;
}
