#include <bits/stdc++.h>
using namespace std;
int p,mu;
int f[105][105];
long long modpow(long long b,long long e,long long m){long long r=1;b%=m;while(e){if(e&1)r=r*b%m;b=b*b%m;e>>=1;}return r;}
void build(){int d=p-1;for(int i=0;i<p;i++)for(int x=0;x<p;x++){long long a=modpow(x,i+1,p),b=modpow(mu,i+1,p);f[i][x]=(int)((a+b)%7);} }
typedef bitset<128> BS;
BS full;
BS classmask[105][7];
vector<BS> pairCand(){
  vector<BS> cand;
  // singles
  for(int i=0;i<p;i++){
    BS G=full;
    for(int x=0;x<p;x++) G &= classmask[x][f[i][x]];
    cand.push_back(G);
  }
  // counts
  static int cnt[105][105];
  for(int i=0;i<p;i++)for(int j=0;j<p;j++)cnt[i][j]=0;
  for(int x=0;x<p;x++){
    for(int r=0;r<7;r++){
      vector<int> L; for(int i=0;i<p;i++) if(f[i][x]==r) L.push_back(i);
      for(int a=0;a<(int)L.size();a++)for(int b=a+1;b<(int)L.size();b++){cnt[L[a]][L[b]]++;cnt[L[b]][L[a]]++;}
    }
  }
  int h=(p+1)/2;
  for(int i=0;i<p;i++)for(int j=i+1;j<p;j++) if(cnt[i][j]>=h){
    BS G=full;
    for(int x=0;x<p;x++) if(f[i][x]==f[j][x]) G &= classmask[x][f[i][x]];
    cand.push_back(G);
  }
  return cand;
}
int main(){
  vector<int> primes; for(int q=2;q<=100;q++){bool ok=true;for(int d=2;d*d<=q;d++)if(q%d==0)ok=false;if(ok)primes.push_back(q);}
  long long totalA=0,totalF=0,maxA=0,maxF=0;int maxAp=0,maxFp=0;
  auto t0=chrono::high_resolution_clock::now();
  for(int pp:primes){ for(int mm=0;mm<pp;mm++){
      p=pp;mu=mm;build();full.reset();for(int i=0;i<p;i++)full.set(i);
      memset(classmask,0,sizeof(classmask));
      for(int x=0;x<p;x++)for(int i=0;i<p;i++)classmask[x][f[i][x]].set(i);
      auto cand=pairCand();
      // dedup
      sort(cand.begin(),cand.end(),[](const BS&A,const BS&B){return A.to_string()<B.to_string();});
      cand.erase(unique(cand.begin(),cand.end(),[](const BS&A,const BS&B){return A==B;}),cand.end());
      // maximal
      sort(cand.begin(),cand.end(),[](const BS&A,const BS&B){return A.count()>B.count();});
      vector<BS> res;
      for(auto&A:cand){bool mx=true;for(auto&B:res) if((A|B)==B){mx=false;break;} if(mx)res.push_back(A);}
      totalA+=cand.size(); totalF+=res.size();
      if((long long)cand.size()>maxA){maxA=cand.size();maxAp=pp;}
      if((long long)res.size()>maxF){maxF=res.size();maxFp=pp;}
  } }
  auto t1=chrono::high_resolution_clock::now();
  double sec=chrono::duration<double>(t1-t0).count();
  printf("primes<=100 all mu: time=%.3fs maxCand=%lld(p=%d) maxF=%lld(p=%d) totalCand=%lld totalF=%lld\n",sec,maxA,maxAp,maxF,maxFp,totalA,totalF);
  return 0;
}

