void build(){int d=p-1;for(int i=0;i<p;i++)for(int x=0;x<p;x++){long long a=modpow(x,i+1,p),b=modpow(mu,i+1,p);f[i][x]=(int)((a+b)%7);} }
typedef bitset<128> BS;
int n; // atoms
vector<array<int,105>> vec;
BS fullAtom, atommask[105][7];
int h;
inline int firstBit(const BS&S){for(int i=0;i<n;i++)if(S[i])return i;return -1;}
bool constantOn(BS S,int x,int &v){v=-1;for(int i=0;i<n;i++)if(S[i]){if(v==-1)v=vec[i][x];else if(vec[i][x]!=v)return false;}return true;}
int agreeCount(BS S){int c=0,v;for(int x=0;x<p;x++)if(constantOn(S,x,v))c++;return c;}
BS closure(BS S){if(S.none())return S;int a=firstBit(S);BS G=fullAtom;for(int x=0;x<p;x++){int v=vec[a][x];if((S&~atommask[x][v]).none())G&=atommask[x][v];}return G;}
int main(){
  vector<int> primes={31,37,41,43,47};
  for(int pp:primes){
    for(int mm=0;mm<pp;mm++){
      p=pp;mu=mm;build();h=(p+1)/2;
      // build atoms
      map<vector<int>,vector<int>> groups;
      for(int i=0;i<p;i++){vector<int> vv(p);for(int x=0;x<p;x++)vv[x]=f[i][x];groups[vv].push_back(i);}
      n=groups.size();vec.clear();
      for(auto&kv:groups){array<int,105> arr;for(int x=0;x<p;x++)arr[x]=kv.first[x];vec.push_back(arr);}
