    totalClosures += (long long)st.size()*n;
    if((long long)visited.size()>maxVisited){maxVisited=visited.size();mvp=pp;}
    if(Q>maxQ)maxQ=Q;
    sumVisited+=visited.size();
  }
  auto t1=chrono::high_resolution_clock::now();
  printf("time=%.3fs maxVisited=%lld(p=%d) sumVisited=%lld maxQ=%lld totalClosures=%lld\n",chrono::duration<double>(t1-t0).count(),maxVisited,mvp,sumVisited,maxQ,totalClosures);
  return 0;
}

