long long modpow(long long b, long long e, long long m){
    long long r=1; b%=m;
    while(e){ if(e&1) r=r*b%m; b=b*b%m; e>>=1; }
    return r;
}
inline int firstBit(const BS &S){ for(int i=0;i<n;i++) if(S[i]) return i; return -1; }
BS closureAndAgree(BS S, int &ac){
    ac = 0;
    if(S.none()) return S;
    int a = firstBit(S);
    BS G = fullAtom;
    for(int x=0;x<p;x++){
        int v = vec[a][x];
        if( (S & ~atommask[x][v]).none() ){ G &= atommask[x][v]; ac++; }
    }
    return G;
}
static string cache[101][101];
static bool cached[101][101];
static bool cacheInit = false;

int main(){
    if(!cacheInit){ memset(cached,0,sizeof(cached)); cacheInit=true; }
    int T; if(scanf("%d",&T)!=1) return 0;
    string out;
    while(T--){
        int pp, mm; scanf("%d %d",&pp,&mm);
